{
  "name": "signal.updated",
  "description": "A selected public signal changed.",
  "delivery": ["webhook"],
  "inputSchema": {
    "type": "object",
    "properties": {"signal_id": {"type": "string"}},
    "required": ["signal_id"],
    "additionalProperties": false
  },
  "payloadSchema": {
    "type": "object",
    "properties": {
      "signal_id": {"type": "string"},
      "version": {"type": "integer"},
      "source_url": {"type": "string"}
